codeMap.nginx:
limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;
server {
    listen 80;
    server_name learnxchain.com www.learnxchain.com;
    return 301 https://learnxchain.com$request_uri;
}
server {
    listen 443 ssl http2;
    server_name learnxchain.com;
    ssl_certificate /etc/letsencrypt/live/learnxchain.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/learnxchain.com/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    gzip on;
    gzip_types text/plain text/css application/json application/javascript;
    location / {
        proxy_pass http://localhost:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        limit_req zone=api_limit burst=20 nodelay;
    }
}

codeMap.tf:
provider "aws" {
  region = "us-east-1"
}
resource "aws_vpc" "production_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true,
  tags = {
    Name = "production-vpc"
  }
}
resource "aws_subnet" "public_subnet_a" {
  vpc_id            = aws_vpc.production_vpc.id,
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  tags = {
    Name = "public-subnet-1a"
  }
}
resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.production_vpc.id
}
output "vpc_id" {
  value = aws_vpc.production_vpc.id
}

codeMap.js:
const redis = require('redis');
const client = redis.createClient({ url: 'redis://localhost:6379' });

async function getCachedUser(userId) {
  await client.connect();
  const cachedData = await client.get('user:' + userId);
  if (cachedData) {
    console.log("Cache hit!");
    return JSON.parse(cachedData);
  }
  const user = await fetchUserFromDatabase(userId);
  await client.setEx('user:' + userId, 3600, JSON.stringify(user));
  return user;
}

